/**
 * The reverb zone presets (ADR 0162 R10, ADR 0333). Five reverbs are generated by the audio core (`IR_GENERATED`:
 * `room`, `corridor`, `hall`, `cave`, `open`, each an `{ rt60, hfDamping, predelayMs }` in
 * `native/audio/crates/audio-dsp/src/convolver/presets.rs`). ADR 0333 adds the prototype's four named spaces as presets
 * over those generated reverbs, each picked for the character its name asks for:
 *
 * - `smallStone` → `room` (0.45 s, HF damping 0.5, 4 ms predelay): a small hard enclosure; a short, dense tail that starts
 *   almost at once.
 * - `canyonHall` → `cave` (3.6 s, HF damping 0.3, 30 ms predelay): the longest and brightest tail with a late onset,
 *   as rock walls far apart give.
 * - `metalTunnel` → `hall` (2.2 s, HF damping 0.4, 18 ms predelay): metal rings and keeps its highs, so a long, bright
 *   tail rather than the corridor's dull one (HF damping 0.6).
 * - `forest` → `open` (0.9 s, HF damping 0.8, 40 ms predelay): sparse, distant reflections off trunks, highs soaked up
 *   by foliage.
 *
 * The prototype's send levels for them (Small stone −6 dB, Canyon hall −12, Metal tunnel −4, Forest −16) are the zone's
 * `wet`, which stays the zone's own field. TODO(ADR 0333): presets with their own reverb times need new generated
 * responses in the core (`presets.rs`); until then these four share the generated five's.
 *
 * Pure; no imports (the decoder worker reads it too).
 */

/** The reverbs the audio core generates, in its preset index order (`myco_ir_generate`'s `preset`). */
export const IR_GENERATED = ["room", "corridor", "hall", "cave", "open"] as const;

/** The built-in reverbs a zone can use without an impulse response. */
export const ZONE_PRESETS = [...IR_GENERATED, "smallStone", "canyonHall", "metalTunnel", "forest"] as const;
/** One of `ZONE_PRESETS`. */
export type ZonePreset = (typeof ZONE_PRESETS)[number];

const BASE: Readonly<Record<string, (typeof IR_GENERATED)[number]>> = { smallStone: "room", canyonHall: "cave", metalTunnel: "hall", forest: "open" };

/** The generated reverb a preset plays (itself for the generated five); an unknown name is returned unchanged. */
export const reverbPresetBase = (preset: string): string => BASE[preset] ?? preset;
